         tmp12 = state%s8*tmp11
         tmp13 = state%s20 + tmp12
         tmp14 = -tmp13
         tmp15 = tmp3 + tmp14
         tmp16 = dot(tmp6, tmp15)
         energy = energy + tmp16
      end if

      state%ready = 3
   end subroutine ssvpe_point_solve

