      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp5(:), tmp6(:), tmp7(:), &
                               tmp8(:), tmp9(:), tmp10(:), tmp11(:), tmp12(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[ssvpe_point_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[ssvpe_point_response_one] hvp_v: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp11(npt), stat=stat)
      if (stat == 0) allocate (tmp12(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[ssvpe_point_response_one] allocation failed")
         return
      end if

      state%op1%points => state%r
      state%op1%a => state%a
      state%op1%c1 => state%s7
      state%op1%c3 => state%s12
      tmp1 = state%a*dv
      call gemv(state%s12, tmp1, tmp2)
      tmp3 = (-0.15915494309189535_wp)*tmp2
      tmp4 = dv + tmp3
      tmp5 = 0.0_wp
      call state%solver%solve(state%op1, .false., tmp4, tmp5, error)
      if (allocated(error)) return
      tmp6 = state%s15*tmp5
      tmp7 = 0.0_wp
      call state%solver%solve(state%op1, .false., dv, tmp7, error)
      if (allocated(error)) return
      tmp8 = state%s15*tmp7
      tmp9 = tmp6 + tmp8
      tmp10 = state%s17*tmp7
      call gemv(state%s12, tmp10, tmp11, trans="t")
      tmp12 = tmp11*state%a
      hvp_v = tmp9 + tmp12
   end subroutine ssvpe_point_response_one

   !> SS(V)PE (point charges): energy derivatives with respect to the solvent parameters
   !>
   !> - For the inputs of the last solve; independent of weights, which does not compute them
   !> - Needs ssvpe_point_solve on the same state first
   !> - Keeps the state as it is; may be repeated in any order
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of ssvpe_point
   !> @param[out] grad_eps  partial derivative of the energy with respect to eps
   !> @param[out] error  error handling; allocated on failure
   subroutine ssvpe_point_param_weights(state, grad_eps, error)
      !> State of ssvpe_point
      type(ssvpe_point_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to eps
      real(wp), intent(out) :: grad_eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp6(:)
      real(wp) :: tmp4, tmp5, tmp7, tmp8, tmp9, tmp10, tmp11

      if (state%matrix_free) then
         call ssvpe_point_mf_param_weights(state, grad_eps, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 3) then
         call fatal_error(error, "[ssvpe_point_param_weights] call ssvpe_point_solve first")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[ssvpe_point_param_weights] allocation failed")
         return
      end if

      state%op1%points => state%r
      state%op1%a => state%a
      state%op1%c1 => state%s7
      state%op1%c3 => state%s12
      call gemv(state%s12, state%s21, tmp1)
      call gemv(state%s7, state%s23, tmp2, trans="t")
      tmp3 = tmp1 + tmp2
      tmp4 = dot(state%s29, tmp3)
      tmp5 = (-0.07957747154594767_wp)*tmp4
      tmp6 = 0.5_wp*state%v
      tmp7 = dot(tmp6, state%s14)
      tmp8 = -tmp7
      tmp9 = tmp5 + tmp8
      tmp10 = state%s1**(-2)
      tmp11 = tmp9*tmp10
      grad_eps = 2.0_wp*tmp11
   end subroutine ssvpe_point_param_weights

   !> SS(V)PE (point charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs ssvpe_point_assemble on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of ssvpe_point
   !> @param[in] eps  relative permittivity of the solvent (inf for a conductor)
   !> @param[out] error  error handling; allocated on failure
   subroutine ssvpe_point_complex_medium(state, eps, error)
      !> State of ssvpe_point
      type(ssvpe_point_complex_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      complex(wp), intent(in) :: eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      complex(wp) :: tmp1, tmp2

      if (state%matrix_free) then
         call ssvpe_point_complex_mf_medium(state, eps, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, "[ssvpe_point_complex_medium] call ssvpe_point_assemble first")
         return
      end if
      state%cx_ready = 0
      if (allocated(state%cx_v)) deallocate (state%cx_v)
      if (allocated(state%cx_s13)) deallocate (state%cx_s13)
      if (allocated(state%cx_s14)) deallocate (state%cx_s14)
      if (allocated(state%cx_s16)) deallocate (state%cx_s16)
      if (allocated(state%cx_s18)) deallocate (state%cx_s18)
      if (allocated(state%cx_s19)) deallocate (state%cx_s19)
      if (allocated(state%cx_s20)) deallocate (state%cx_s20)
      if (allocated(state%cx_s21)) deallocate (state%cx_s21)
      if (allocated(state%cx_s22)) deallocate (state%cx_s22)
      if (allocated(state%cx_s23)) deallocate (state%cx_s23)
      if (allocated(state%cx_s25)) deallocate (state%cx_s25)
      if (allocated(state%cx_s26)) deallocate (state%cx_s26)
      if (allocated(state%cx_s27)) deallocate (state%cx_s27)
      if (allocated(state%cx_s29)) deallocate (state%cx_s29)
      if (allocated(state%cx_s30)) deallocate (state%cx_s30)
      if (allocated(state%cx_s31)) deallocate (state%cx_s31)
      if (allocated(state%cx_s32)) deallocate (state%cx_s32)
      if (allocated(state%cx_s33)) deallocate (state%cx_s33)
      if (allocated(state%cx_s34)) deallocate (state%cx_s34)
      if (allocated(state%cx_s35)) deallocate (state%cx_s35)
      if (allocated(state%cx_s36)) deallocate (state%cx_s36)
      if (stat == 0) allocate (state%cx_v(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s13(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s14(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s16(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s18(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s19(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s20(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s21(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s22(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s23(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s25(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s26(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s27(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s29(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s30(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s31(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s32(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s33(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s34(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s35(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s36(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[ssvpe_point_complex_medium] allocation failed")
         return
      end if
      state%cx_s14 = 0.0_wp
      state%cx_s16 = 0.0_wp
      state%cx_ready = 1
      state%cx_assembled = state%assembled
      ! Inputs that do not enter these outputs
      associate (unused1 => eps)
      end associate

      state%op3%npt = npt
      state%op3%npoint = npt
      state%op3%id = 3
      state%op3%points => state%r
      state%op3%symmetric = .true.
      state%op3%a => state%a
      state%op3%c1 => state%s7
      state%cx_s1 = eps + 1.0_wp
      tmp1 = 1.0_wp/state%cx_s1
      tmp2 = (-2.0_wp)*tmp1
      state%cx_s2 = 1.0_wp + tmp2
      state%cx_s8 = (-0.07957747154594767_wp)*state%cx_s2
      state%op3%c2 = state%cx_s8
      state%op3%c3 => state%s12
      call state%solver%setup_complex(state%op3, error)
      if (allocated(error)) return
      state%cx_s3 = -state%cx_s2
      state%cx_s15 = (-0.5_wp)*state%cx_s2
      state%cx_s17 = 0.07957747154594767_wp*state%cx_s2
      state%cx_s28 = 0.5_wp*state%cx_s2

      state%cx_ready = 2
   end subroutine ssvpe_point_complex_medium

   !> SS(V)PE (point charges): energy, solution and gradient for v
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs ssvpe_point_complex_medium on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of ssvpe_point
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] q  apparent surface charges
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] error  error handling; allocated on failure
   subroutine ssvpe_point_complex_solve(state, v, energy, q, grad_v, error)
      !> State of ssvpe_point
      type(ssvpe_point_complex_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      complex(wp), contiguous, intent(in) :: v(:)
      !> Solvation energy
      complex(wp), intent(out) :: energy
      !> Apparent surface charges
      complex(wp), contiguous, intent(out) :: q(:)
      !> Partial derivative of the energy with respect to v
      complex(wp), contiguous, intent(out) :: grad_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp2(:), tmp3(:), tmp6(:), tmp7(:), tmp8(:), tmp9(:), tmp10(:), &
                               tmp11(:), tmp18(:), tmp19(:), tmp21(:), tmp22(:)
      complex(wp), allocatable :: tmp1(:), tmp4(:), tmp5(:), tmp13(:), tmp14(:), tmp15(:), &
                                  tmp16(:), tmp17(:), tmp20(:), tmp23(:), tmp24(:), tmp25(:), &
                                  tmp26(:), tmp27(:)
      complex(wp) :: tmp12, tmp28

      if (state%matrix_free) then
         call ssvpe_point_complex_mf_solve(state, v, energy, q, grad_v, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%cx_ready < 2 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[ssvpe_point_complex_solve] call ssvpe_point_complex_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[ssvpe_point_complex_solve] v: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[ssvpe_point_complex_solve] q: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[ssvpe_point_complex_solve] grad_v: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp11(npt), stat=stat)
      if (stat == 0) allocate (tmp13(npt), stat=stat)
      if (stat == 0) allocate (tmp14(npt), stat=stat)
      if (stat == 0) allocate (tmp15(npt), stat=stat)
      if (stat == 0) allocate (tmp16(npt), stat=stat)
      if (stat == 0) allocate (tmp17(npt), stat=stat)
      if (stat == 0) allocate (tmp18(npt), stat=stat)
      if (stat == 0) allocate (tmp19(npt), stat=stat)
      if (stat == 0) allocate (tmp20(npt), stat=stat)
      if (stat == 0) allocate (tmp21(npt), stat=stat)
      if (stat == 0) allocate (tmp22(npt), stat=stat)
      if (stat == 0) allocate (tmp23(npt), stat=stat)
      if (stat == 0) allocate (tmp24(npt), stat=stat)
      if (stat == 0) allocate (tmp25(npt), stat=stat)
      if (stat == 0) allocate (tmp26(npt), stat=stat)
      if (stat == 0) allocate (tmp27(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[ssvpe_point_complex_solve] allocation failed")
         return
      end if
      state%cx_ready = 2

      state%op3%points => state%r
      state%op3%a => state%a
      state%op3%c1 => state%s7
      state%op3%c3 => state%s12
      state%cx_v = v
      state%cx_s13 = state%a*state%cx_v
      call gemv(state%s12, real(state%cx_s13, wp), tmp2)
      call gemv(state%s12, aimag(state%cx_s13), tmp3)
      tmp1 = cmplx(tmp2, tmp3, wp)
      tmp4 = (-0.15915494309189535_wp)*tmp1
      tmp5 = state%cx_v + tmp4
      call state%solver%solve_complex(state%op3, .false., tmp5, state%cx_s14, error)
      if (allocated(error)) return
      call state%solver%solve_complex(state%op3, .false., state%cx_v, state%cx_s16, error)
      if (allocated(error)) return
      state%cx_s18 = state%cx_s17*state%cx_s16
      call gemv(state%s12, real(state%cx_s18, wp), tmp6, trans="t")
      call gemv(state%s12, aimag(state%cx_s18), tmp7, trans="t")
      state%cx_s19 = cmplx(tmp6, tmp7, wp)
      call gemv(state%s7, real(state%cx_s14, wp), tmp8)
      call gemv(state%s7, aimag(state%cx_s14), tmp9)
      state%cx_s20 = cmplx(tmp8, tmp9, wp)
      state%cx_s21 = state%a*state%cx_s20
      call gemv(state%s12, real(state%cx_s14, wp), tmp10, trans="t")
      call gemv(state%s12, aimag(state%cx_s14), tmp11, trans="t")
      state%cx_s22 = cmplx(tmp10, tmp11, wp)
      state%cx_s23 = state%a*state%cx_s22
      state%cx_s29 = state%cx_s28*state%cx_s16
      q = state%cx_s3*state%cx_s14
      tmp12 = sum(state%cx_v*q)
      energy = 0.5_wp*tmp12
      tmp13 = state%cx_s15*state%cx_s14
      tmp14 = state%cx_s15*state%cx_s16
      tmp15 = tmp13 + tmp14
      tmp16 = state%cx_s19*state%a
      grad_v = tmp15 + tmp16
      if (state%solver%inexact()) then
         ! First-order correction for the residuals of the solves
         call gemv(state%s12, real(state%cx_s21, wp), tmp18)
         call gemv(state%s12, aimag(state%cx_s21), tmp19)
         tmp17 = cmplx(tmp18, tmp19, wp)
         call gemv(state%s7, real(state%cx_s23, wp), tmp21, trans="t")
         call gemv(state%s7, aimag(state%cx_s23), tmp22, trans="t")
         tmp20 = cmplx(tmp21, tmp22, wp)
         tmp23 = tmp17 + tmp20
         tmp24 = state%cx_s8*tmp23
         tmp25 = state%cx_s20 + tmp24
         tmp26 = -tmp25
         tmp27 = tmp5 + tmp26
         tmp28 = sum(tmp14*tmp27)
         energy = energy + tmp28
      end if

      state%cx_ready = 3
   end subroutine ssvpe_point_complex_solve

   !> SS(V)PE (point charges): energy gradient with respect to the cavity inputs
   !>
   !> - For the inputs of the last solve
   !> - Needs ssvpe_point_complex_solve on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of ssvpe_point
   !> @param[out] grad_r  partial derivative of the energy with respect to r
   !> @param[out] grad_n  partial derivative of the energy with respect to n
   !> @param[out] grad_k1  partial derivative of the energy with respect to k1
   !> @param[out] grad_k2  partial derivative of the energy with respect to k2
   !> @param[out] grad_a  partial derivative of the energy with respect to a
   !> @param[out] error  error handling; allocated on failure
   subroutine ssvpe_point_complex_weights(state, grad_r, grad_n, grad_k1, grad_k2, grad_a, error)
      !> State of ssvpe_point
      type(ssvpe_point_complex_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to r
      complex(wp), contiguous, intent(out) :: grad_r(:, :)
      !> Partial derivative of the energy with respect to n
      complex(wp), contiguous, intent(out) :: grad_n(:, :)
      !> Partial derivative of the energy with respect to k1
      complex(wp), contiguous, intent(out) :: grad_k1(:)
      !> Partial derivative of the energy with respect to k2
      complex(wp), contiguous, intent(out) :: grad_k2(:)
      !> Partial derivative of the energy with respect to a
      complex(wp), contiguous, intent(out) :: grad_a(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp2(:), tmp3(:), tmp4(:), tmp5(:)
      real(wp) :: tmp10, tmp11, tmp12, tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, tmp20, &
                  tmp21, tmp26, tmp27, tmp28, tmp29, tmp30, tmp31
      complex(wp), allocatable :: tmp6(:), tmp7(:), tmp8(:), tmp9(:), tmp22(:), tmp23(:), &
                                  tmp24(:), tmp25(:), tmp32(:), tmp33(:), tmp34(:), tmp35(:), &
                                  tmp36(:), tmp37(:), tmp125(:), tmp126(:), tmp127(:), tmp128(:), &
                                  tmp129(:), tmp130(:), tmp131(:), tmp132(:)
      complex(wp) :: tmp1
      complex(wp), allocatable :: tmp32_p(:), tmp33_p(:), tmp34_p(:)
      integer :: i, j

      if (state%matrix_free) then
         call ssvpe_point_complex_mf_weights(state, grad_r, grad_n, grad_k1, grad_k2, grad_a, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[ssvpe_point_complex_weights] call ssvpe_point_complex_solve first")
         return
      end if
      if (any(shape(grad_r) /= [3, npt])) then
         call fatal_error(error, "[ssvpe_point_complex_weights] grad_r: wrong shape")
         return
      end if
      if (any(shape(grad_n) /= [3, npt])) then
         call fatal_error(error, "[ssvpe_point_complex_weights] grad_n: wrong shape")
         return
      end if
      if (any(shape(grad_k1) /= [npt])) then
         call fatal_error(error, "[ssvpe_point_complex_weights] grad_k1: wrong shape")
         return
      end if
      if (any(shape(grad_k2) /= [npt])) then
         call fatal_error(error, "[ssvpe_point_complex_weights] grad_k2: wrong shape")
         return
      end if
      if (any(shape(grad_a) /= [npt])) then
         call fatal_error(error, "[ssvpe_point_complex_weights] grad_a: wrong shape")
         return
      end if
      allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp22(npt), stat=stat)
      if (stat == 0) allocate (tmp23(npt), stat=stat)
      if (stat == 0) allocate (tmp24(npt), stat=stat)
      if (stat == 0) allocate (tmp25(npt), stat=stat)
      if (stat == 0) allocate (tmp32(npt), stat=stat)
      if (stat == 0) allocate (tmp33(npt), stat=stat)
      if (stat == 0) allocate (tmp34(npt), stat=stat)
      if (stat == 0) allocate (tmp35(npt), stat=stat)
      if (stat == 0) allocate (tmp36(npt), stat=stat)
      if (stat == 0) allocate (tmp37(npt), stat=stat)
      if (stat == 0) allocate (tmp125(npt), stat=stat)
      if (stat == 0) allocate (tmp126(npt), stat=stat)
      if (stat == 0) allocate (tmp127(npt), stat=stat)
      if (stat == 0) allocate (tmp128(npt), stat=stat)
      if (stat == 0) allocate (tmp129(npt), stat=stat)
      if (stat == 0) allocate (tmp130(npt), stat=stat)
      if (stat == 0) allocate (tmp131(npt), stat=stat)
      if (stat == 0) allocate (tmp132(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[ssvpe_point_complex_weights] allocation failed")
         return
      end if
      state%cx_ready = 3

