   !> @param[out] error  error handling; allocated on failure
   subroutine ssvpe_point_complex_param_weights(state, grad_eps, error)
      !> State of ssvpe_point
      type(ssvpe_point_complex_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to eps
      complex(wp), intent(out) :: grad_eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp2(:), tmp3(:), tmp5(:), tmp6(:)
      complex(wp), allocatable :: tmp1(:), tmp4(:), tmp7(:), tmp10(:)
      complex(wp) :: tmp8, tmp9, tmp11, tmp12, tmp13, tmp14, tmp15

      if (state%matrix_free) then
         call ssvpe_point_complex_mf_param_weights(state, grad_eps, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[ssvpe_point_complex_param_weights] call ssvpe_point_complex_solve first")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[ssvpe_point_complex_param_weights] allocation failed")
         return
      end if

      state%op3%points => state%r
      state%op3%a => state%a
      state%op3%c1 => state%s7
      state%op3%c3 => state%s12
      call gemv(state%s12, real(state%cx_s21, wp), tmp2)
      call gemv(state%s12, aimag(state%cx_s21), tmp3)
      tmp1 = cmplx(tmp2, tmp3, wp)
      call gemv(state%s7, real(state%cx_s23, wp), tmp5, trans="t")
      call gemv(state%s7, aimag(state%cx_s23), tmp6, trans="t")
