      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp5(:), tmp12(:), tmp13(:), &
                               tmp14(:), tmp15(:), tmp48(:), tmp49(:), tmp50(:), tmp51(:), &
                               tmp52(:), tmp53(:)
      real(wp) :: tmp6, tmp7, tmp8, tmp9, tmp10, tmp11
      real(wp), allocatable :: tmp4_p(:)
      integer :: i, j

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[ssvpe_point_mf_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[ssvpe_point_mf_response_one] hvp_v: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp12(npt), stat=stat)
      if (stat == 0) allocate (tmp13(npt), stat=stat)
      if (stat == 0) allocate (tmp14(npt), stat=stat)
      if (stat == 0) allocate (tmp15(npt), stat=stat)
      if (stat == 0) allocate (tmp48(npt), stat=stat)
      if (stat == 0) allocate (tmp49(npt), stat=stat)
      if (stat == 0) allocate (tmp50(npt), stat=stat)
      if (stat == 0) allocate (tmp51(npt), stat=stat)
      if (stat == 0) allocate (tmp52(npt), stat=stat)
      if (stat == 0) allocate (tmp53(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[ssvpe_point_mf_response_one] allocation failed")
         return
      end if

      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%n => state%n
      state%op2%k1 => state%k1
      state%op2%k2 => state%k2
      state%op2%a => state%a
      tmp1 = state%a*dv
      tmp2 = 0.0_wp
      call state%solver%solve(state%op2, .false., dv, tmp2, error)
      if (allocated(error)) return
      tmp3 = state%s17*tmp2
      do i = 1, npt
         tmp6 = state%k1(i) + state%k2(i)
         tmp7 = 1.0_wp/state%a(i)
         tmp8 = 12.566370614359172_wp*tmp7
         tmp9 = sqrt(tmp8)
         tmp10 = tmp6*tmp9
         tmp11 = (-0.26735_wp)*tmp10
         tmp5(i) = tmp11
      end do
      tmp12 = tmp5*tmp1
      tmp13 = (-0.15915494309189535_wp)*tmp12
      tmp4 = tmp13
      tmp15 = tmp5*tmp3
      tmp14 = tmp15
      block
         real(wp) :: tmp17, tmp18, tmp19, tmp20, tmp21, tmp22, tmp23, tmp24, tmp25, tmp28, tmp32, &
                     tmp16, tmp26, tmp27, tmp29, tmp30, tmp31, tmp33, tmp34, tmp35, tmp36, tmp37, &
                     tmp38, tmp39, tmp40, tmp41, tmp42, tmp43, tmp44, tmp45, tmp46, tmp47

         !$omp parallel &
         !$omp& private(i, j, tmp4_p) &
         !$omp& shared(npt, state, tmp1, tmp14, tmp3, tmp4) &
         !$omp& default(private)
         allocate (tmp4_p(npt))
         tmp4_p = 0.0_wp
         !$omp do schedule(static)
         do j = 1, npt
            tmp17 = state%s9(j)
            tmp18 = state%s4(j)
            tmp19 = state%s5(j)
            tmp20 = state%s10(j)
            tmp21 = state%s6(j)
            tmp22 = state%s11(j)
            tmp23 = tmp1(j)
            tmp24 = tmp3(j)
            tmp25 = -tmp18
            tmp28 = -tmp19
            tmp32 = -tmp21
            tmp16 = 0.0_wp
            !$omp simd &
            !$omp& private(tmp26, tmp27, tmp29, tmp30, tmp31, tmp33, tmp34, tmp35) &
            !$omp& private(tmp36, tmp37, tmp38, tmp39, tmp40, tmp41, tmp42, tmp43) &
            !$omp& private(tmp44, tmp45, tmp46, tmp47) &
            !$omp& reduction(+: tmp16)
            do i = 1, j - 1
               tmp26 = state%s4(i) + tmp25
               tmp27 = tmp17*tmp26
               tmp29 = state%s5(i) + tmp28
               tmp30 = tmp29*tmp20
               tmp31 = tmp27 + tmp30
               tmp33 = state%s6(i) + tmp32
               tmp34 = tmp33*tmp22
               tmp35 = tmp31 + tmp34
               tmp36 = tmp26**(2)
               tmp37 = tmp29**(2)
               tmp38 = tmp36 + tmp37
               tmp39 = tmp33**(2)
               tmp40 = tmp38 + tmp39
               tmp41 = 1.0_wp/sqrt(tmp40)
               tmp42 = tmp41**(3)
               tmp43 = tmp35*tmp42
               tmp44 = tmp43*tmp23
               tmp45 = (-0.15915494309189535_wp)*tmp44
               tmp4_p(i) = tmp4_p(i) + tmp45
               tmp46 = tmp35*tmp3(i)
               tmp47 = tmp46*tmp42
               tmp16 = tmp16 + tmp47
            end do
            !$omp simd &
            !$omp& private(tmp26, tmp27, tmp29, tmp30, tmp31, tmp33, tmp34, tmp35) &
            !$omp& private(tmp36, tmp37, tmp38, tmp39, tmp40, tmp41, tmp42, tmp43) &
            !$omp& private(tmp44, tmp45, tmp46, tmp47) &
            !$omp& reduction(+: tmp16)
            do i = j + 1, npt
               tmp26 = state%s4(i) + tmp25
               tmp27 = tmp17*tmp26
               tmp29 = state%s5(i) + tmp28
               tmp30 = tmp29*tmp20
               tmp31 = tmp27 + tmp30
               tmp33 = state%s6(i) + tmp32
               tmp34 = tmp33*tmp22
               tmp35 = tmp31 + tmp34
               tmp36 = tmp26**(2)
               tmp37 = tmp29**(2)
               tmp38 = tmp36 + tmp37
               tmp39 = tmp33**(2)
               tmp40 = tmp38 + tmp39
               tmp41 = 1.0_wp/sqrt(tmp40)
               tmp42 = tmp41**(3)
               tmp43 = tmp35*tmp42
               tmp44 = tmp43*tmp23
               tmp45 = (-0.15915494309189535_wp)*tmp44
               tmp4_p(i) = tmp4_p(i) + tmp45
               tmp46 = tmp35*tmp3(i)
               tmp47 = tmp46*tmp42
               tmp16 = tmp16 + tmp47
            end do
            tmp14(j) = tmp14(j) + tmp16
         end do
         !$omp end do
         !$omp critical (pcmgen_sum)
         tmp4 = tmp4 + tmp4_p
         !$omp end critical (pcmgen_sum)
         deallocate (tmp4_p)
         !$omp end parallel
      end block
      tmp48 = dv + tmp4
      tmp49 = 0.0_wp
      call state%solver%solve(state%op2, .false., tmp48, tmp49, error)
      if (allocated(error)) return
      tmp50 = state%s15*tmp49
      tmp51 = state%s15*tmp2
      tmp52 = tmp50 + tmp51
      tmp53 = tmp14*state%a
      hvp_v = tmp52 + tmp53
   end subroutine ssvpe_point_mf_response_one

   !> SS(V)PE (point charges): energy derivatives with respect to the solvent parameters
   !>
   !> - For the inputs of the last solve; independent of weights, which does not compute them
   !> - Needs ssvpe_point_solve on the same state first
   !> - Keeps the state as it is; may be repeated in any order
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of ssvpe_point
   !> @param[out] grad_eps  partial derivative of the energy with respect to eps
   !> @param[out] error  error handling; allocated on failure
   subroutine ssvpe_point_mf_param_weights(state, grad_eps, error)
      !> State of ssvpe_point
      type(ssvpe_point_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to eps
      real(wp), intent(out) :: grad_eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp9(:), tmp10(:), tmp15(:), tmp16(:), tmp49(:)
      real(wp) :: tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp11, tmp12, tmp13, tmp14, tmp47, tmp48, &
                  tmp50, tmp51, tmp52, tmp53, tmp54
      real(wp), allocatable :: tmp1_p(:)
      integer :: i, j

      stat = 0
      npt = state%npt
      if (state%ready < 3) then
         call fatal_error(error, "[ssvpe_point_mf_param_weights] call ssvpe_point_solve first")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp15(npt), stat=stat)
      if (stat == 0) allocate (tmp16(npt), stat=stat)
      if (stat == 0) allocate (tmp49(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[ssvpe_point_mf_param_weights] allocation failed")
         return
      end if

      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%n => state%n
      state%op2%k1 => state%k1
      state%op2%k2 => state%k2
      state%op2%a => state%a
      do i = 1, npt
         tmp3 = state%k1(i) + state%k2(i)
         tmp4 = 1.0_wp/state%a(i)
         tmp5 = 12.566370614359172_wp*tmp4
         tmp6 = sqrt(tmp5)
         tmp7 = tmp3*tmp6
         tmp8 = (-0.26735_wp)*tmp7
         tmp2(i) = tmp8
      end do
      tmp9 = tmp2*state%s21
      do i = 1, npt
         tmp11 = 1.0_wp/state%a(i)
         tmp12 = 12.566370614359172_wp*tmp11
         tmp13 = sqrt(tmp12)
         tmp14 = 1.0694_wp*tmp13
         tmp10(i) = tmp14
      end do
      tmp15 = tmp10*state%s23
      tmp16 = tmp9 + tmp15
      tmp1 = tmp16
      block
         real(wp) :: tmp18, tmp19, tmp20, tmp21, tmp22, tmp23, tmp24, tmp25, tmp26, tmp29, tmp33, &
                     tmp17, tmp27, tmp28, tmp30, tmp31, tmp32, tmp34, tmp35, tmp36, tmp37, tmp38, &
                     tmp39, tmp40, tmp41, tmp42, tmp43, tmp44, tmp45, tmp46

         !$omp parallel &
         !$omp& private(i, j, tmp1_p) &
         !$omp& shared(npt, state, tmp1) &
         !$omp& default(private)
         allocate (tmp1_p(npt))
         tmp1_p = 0.0_wp
         !$omp do schedule(static)
         do j = 1, npt
            tmp18 = state%s9(j)
            tmp19 = state%s4(j)
            tmp20 = state%s5(j)
            tmp21 = state%s10(j)
            tmp22 = state%s6(j)
            tmp23 = state%s11(j)
            tmp24 = state%s21(j)
            tmp25 = state%s23(j)
            tmp26 = -tmp19
            tmp29 = -tmp20
            tmp33 = -tmp22
            tmp17 = 0.0_wp
            !$omp simd &
            !$omp& private(tmp27, tmp28, tmp30, tmp31, tmp32, tmp34, tmp35, tmp36) &
            !$omp& private(tmp37, tmp38, tmp39, tmp40, tmp41, tmp42, tmp43, tmp44) &
            !$omp& private(tmp45, tmp46) &
            !$omp& reduction(+: tmp17)
            do i = 1, j - 1
               tmp27 = state%s4(i) + tmp26
               tmp28 = tmp18*tmp27
               tmp30 = state%s5(i) + tmp29
               tmp31 = tmp30*tmp21
               tmp32 = tmp28 + tmp31
               tmp34 = state%s6(i) + tmp33
               tmp35 = tmp34*tmp23
               tmp36 = tmp32 + tmp35
               tmp37 = tmp27**(2)
               tmp38 = tmp30**(2)
               tmp39 = tmp37 + tmp38
               tmp40 = tmp34**(2)
               tmp41 = tmp39 + tmp40
               tmp42 = 1.0_wp/sqrt(tmp41)
               tmp43 = tmp42**(3)
               tmp44 = tmp36*tmp43
               tmp45 = tmp44*tmp24
               tmp1_p(i) = tmp1_p(i) + tmp45
               tmp46 = tmp42*state%s23(i)
               tmp17 = tmp17 + tmp46
            end do
            !$omp simd &
            !$omp& private(tmp27, tmp28, tmp30, tmp31, tmp32, tmp34, tmp35, tmp36) &
            !$omp& private(tmp37, tmp38, tmp39, tmp40, tmp41, tmp42, tmp43, tmp44) &
            !$omp& private(tmp45, tmp46) &
            !$omp& reduction(+: tmp17)
            do i = j + 1, npt
               tmp27 = state%s4(i) + tmp26
               tmp28 = tmp18*tmp27
               tmp30 = state%s5(i) + tmp29
               tmp31 = tmp30*tmp21
               tmp32 = tmp28 + tmp31
               tmp34 = state%s6(i) + tmp33
               tmp35 = tmp34*tmp23
               tmp36 = tmp32 + tmp35
               tmp37 = tmp27**(2)
               tmp38 = tmp30**(2)
               tmp39 = tmp37 + tmp38
               tmp40 = tmp34**(2)
               tmp41 = tmp39 + tmp40
               tmp42 = 1.0_wp/sqrt(tmp41)
               tmp43 = tmp42**(3)
               tmp44 = tmp36*tmp43
               tmp45 = tmp44*tmp24
               tmp1_p(i) = tmp1_p(i) + tmp45
               tmp46 = tmp42*state%s23(i)
               tmp17 = tmp17 + tmp46
            end do
            tmp1_p(j) = tmp1_p(j) + tmp17
         end do
         !$omp end do
         !$omp critical (pcmgen_sum)
         tmp1 = tmp1 + tmp1_p
         !$omp end critical (pcmgen_sum)
         deallocate (tmp1_p)
         !$omp end parallel
      end block
      tmp47 = dot(state%s29, tmp1)
      tmp48 = (-0.07957747154594767_wp)*tmp47
      tmp49 = 0.5_wp*state%v
      tmp50 = dot(tmp49, state%s14)
      tmp51 = -tmp50
      tmp52 = tmp48 + tmp51
      tmp53 = state%s1**(-2)
      tmp54 = tmp52*tmp53
      grad_eps = 2.0_wp*tmp54
   end subroutine ssvpe_point_mf_param_weights

   !> SS(V)PE (point charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs ssvpe_point_assemble on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of ssvpe_point
   !> @param[in] eps  relative permittivity of the solvent (inf for a conductor)
   !> @param[out] error  error handling; allocated on failure
   subroutine ssvpe_point_complex_mf_medium(state, eps, error)
      !> State of ssvpe_point
      type(ssvpe_point_complex_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      complex(wp), intent(in) :: eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      complex(wp) :: tmp1, tmp2

      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, "[ssvpe_point_complex_mf_medium] call ssvpe_point_assemble first")
         return
      end if
      state%cx_ready = 0
      if (allocated(state%cx_v)) deallocate (state%cx_v)
      if (allocated(state%cx_s13)) deallocate (state%cx_s13)
      if (allocated(state%cx_s14)) deallocate (state%cx_s14)
      if (allocated(state%cx_s16)) deallocate (state%cx_s16)
      if (allocated(state%cx_s18)) deallocate (state%cx_s18)
      if (allocated(state%cx_s19)) deallocate (state%cx_s19)
      if (allocated(state%cx_s20)) deallocate (state%cx_s20)
      if (allocated(state%cx_s21)) deallocate (state%cx_s21)
      if (allocated(state%cx_s22)) deallocate (state%cx_s22)
      if (allocated(state%cx_s23)) deallocate (state%cx_s23)
      if (allocated(state%cx_s25)) deallocate (state%cx_s25)
      if (allocated(state%cx_s26)) deallocate (state%cx_s26)
      if (allocated(state%cx_s27)) deallocate (state%cx_s27)
      if (allocated(state%cx_s29)) deallocate (state%cx_s29)
      if (allocated(state%cx_s30)) deallocate (state%cx_s30)
      if (allocated(state%cx_s31)) deallocate (state%cx_s31)
      if (allocated(state%cx_s32)) deallocate (state%cx_s32)
      if (allocated(state%cx_s33)) deallocate (state%cx_s33)
      if (allocated(state%cx_s34)) deallocate (state%cx_s34)
      if (allocated(state%cx_s35)) deallocate (state%cx_s35)
      if (allocated(state%cx_s36)) deallocate (state%cx_s36)
      if (stat == 0) allocate (state%cx_v(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s13(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s14(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s16(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s18(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s19(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s20(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s21(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s22(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s23(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s25(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s26(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s27(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s29(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s30(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s31(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s32(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s33(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s34(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s35(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s36(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[ssvpe_point_complex_mf_medium] allocation failed")
         return
      end if
      state%cx_s14 = 0.0_wp
      state%cx_s16 = 0.0_wp
      state%cx_ready = 1
      state%cx_assembled = state%assembled
      ! Inputs that do not enter these outputs
      associate (unused1 => eps)
      end associate

      state%op4%npt = npt
      state%op4%npoint = npt
      state%op4%id = 4
      state%op4%points => state%r
      state%op4%symmetric = .true.
      state%op4%r => state%r
      state%op4%n => state%n
      state%op4%k1 => state%k1
      state%op4%k2 => state%k2
      state%op4%a => state%a
      state%cx_s1 = eps + 1.0_wp
      tmp1 = 1.0_wp/state%cx_s1
      tmp2 = (-2.0_wp)*tmp1
      state%cx_s2 = 1.0_wp + tmp2
      state%cx_s8 = (-0.07957747154594767_wp)*state%cx_s2
      state%op4%c1 = state%cx_s8
      call state%solver%setup_complex(state%op4, error)
      if (allocated(error)) return
      state%cx_s3 = -state%cx_s2
      state%cx_s15 = (-0.5_wp)*state%cx_s2
      state%cx_s17 = 0.07957747154594767_wp*state%cx_s2
      state%cx_s28 = 0.5_wp*state%cx_s2

      state%cx_ready = 2
   end subroutine ssvpe_point_complex_mf_medium

   !> SS(V)PE (point charges): energy, solution and gradient for v
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs ssvpe_point_complex_medium on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of ssvpe_point
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] q  apparent surface charges
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] error  error handling; allocated on failure
   subroutine ssvpe_point_complex_mf_solve(state, v, energy, q, grad_v, error)
      !> State of ssvpe_point
      type(ssvpe_point_complex_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      complex(wp), contiguous, intent(in) :: v(:)
      !> Solvation energy
      complex(wp), intent(out) :: energy
      !> Apparent surface charges
      complex(wp), contiguous, intent(out) :: q(:)
      !> Partial derivative of the energy with respect to v
      complex(wp), contiguous, intent(out) :: grad_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp2(:), tmp47(:)
      real(wp) :: tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp48, tmp49, tmp50, tmp51
      complex(wp), allocatable :: tmp1(:), tmp9(:), tmp10(:), tmp11(:), tmp12(:), tmp45(:), &
                                  tmp46(:), tmp52(:), tmp53(:), tmp54(:), tmp85(:), tmp86(:), &
                                  tmp87(:), tmp88(:), tmp89(:), tmp90(:), tmp118(:), tmp119(:), &
                                  tmp138(:), tmp139(:), tmp140(:), tmp141(:), tmp142(:)
      complex(wp) :: tmp84, tmp143
      complex(wp), allocatable :: tmp1_p(:), tmp46_p(:), tmp89_p(:)
      integer :: i, j

      stat = 0
      npt = state%npt
      if (state%cx_ready < 2 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[ssvpe_point_complex_mf_solve] call ssvpe_point_complex_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[ssvpe_point_complex_mf_solve] v: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[ssvpe_point_complex_mf_solve] q: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[ssvpe_point_complex_mf_solve] grad_v: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp11(npt), stat=stat)
      if (stat == 0) allocate (tmp12(npt), stat=stat)
      if (stat == 0) allocate (tmp45(npt), stat=stat)
      if (stat == 0) allocate (tmp46(npt), stat=stat)
      if (stat == 0) allocate (tmp47(npt), stat=stat)
      if (stat == 0) allocate (tmp52(npt), stat=stat)
      if (stat == 0) allocate (tmp53(npt), stat=stat)
      if (stat == 0) allocate (tmp54(npt), stat=stat)
      if (stat == 0) allocate (tmp85(npt), stat=stat)
      if (stat == 0) allocate (tmp86(npt), stat=stat)
      if (stat == 0) allocate (tmp87(npt), stat=stat)
      if (stat == 0) allocate (tmp88(npt), stat=stat)
      if (stat == 0) allocate (tmp89(npt), stat=stat)
      if (stat == 0) allocate (tmp90(npt), stat=stat)
