                  tmp105 = tmp104**(2)
                  tmp106 = tmp102 + tmp105
                  tmp108 = self%r(3, i) + tmp107
                  tmp109 = tmp108**(2)
                  tmp110 = tmp106 + tmp109
                  tmp111 = 1.0_wp/sqrt(tmp110)
                  tmp112 = tmp111*tmp92(i)
                  tmp95 = tmp95 + tmp112
               end do
               tmp93(j) = tmp93(j) + tmp95
            end do
            !$omp end do
            !$omp end parallel
         end block
         tmp113 = tmp26 + tmp93
         tmp114 = self%c1*tmp113
         y = tmp1 + tmp114
      end block
   end subroutine ssvpe_point_op4_apply

   !> Form operator 4 of the points idx alone
   !>
   !> - Its expression with every kernel, diagonal and point vector restricted
   !>   to idx: the principal submatrix unless the operator has matrix products
   !> - Points in the order of idx
   !>
   !> @param[in]  self  operator
   !> @param[in]  idx   point indices (nb distinct values in 1..npoint)
   !> @param[out] a     matrix of shape (nb, nb)
   !> @param[out] error  error handling; allocated on a wrong shape or failed allocation
   subroutine ssvpe_point_op4_assemble_block(self, idx, a, error)
      !> Operator
      class(ssvpe_point_op4), intent(in) :: self
      !> Point indices
      integer, contiguous, intent(in) :: idx(:)
      !> Operator matrix of the points
      complex(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: nb
      integer :: stat
      real(wp), allocatable :: tmp3(:), tmp4(:), tmp5(:)
      real(wp), allocatable :: tmp6(:, :), tmp23(:, :), tmp58(:, :), tmp59(:, :), tmp60(:, :), &
                               tmp61(:, :)
      real(wp), allocatable :: tmp1(:, :), tmp2(:, :)
      real(wp) :: tmp19, tmp20, tmp21, tmp22, tmp52, tmp53, tmp54, tmp55, tmp56, tmp57
      complex(wp), allocatable :: tmp62(:, :)
      integer :: i, j

      nb = size(idx)
      if (any(shape(a) /= [nb, nb])) then
         call fatal_error(error, "[ssvpe_point_op4_assemble_block] a: wrong shape")
         return
      end if
      allocate (tmp1(3, nb), stat=stat)
      if (stat == 0) allocate (tmp2(3, nb), stat=stat)
      if (stat == 0) allocate (tmp3(nb), stat=stat)
      if (stat == 0) allocate (tmp4(nb), stat=stat)
      if (stat == 0) allocate (tmp5(nb), stat=stat)
      if (stat == 0) allocate (tmp6(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp23(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp58(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp59(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp60(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp61(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp62(nb, nb), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[ssvpe_point_op4_assemble_block] allocation failed")
         return
      end if
      tmp1 = self%r(:, idx)
      tmp2 = self%n(:, idx)
      tmp3 = self%k1(idx)
      tmp4 = self%k2(idx)
      tmp5 = self%a(idx)
      block
         real(wp) :: tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, tmp13, tmp14, tmp15, tmp16, tmp17, tmp18

         !$omp parallel do schedule(dynamic, 16) &
         !$omp& private(i) &
         !$omp& shared(nb, tmp1, tmp6) &
         !$omp& default(private)
         do j = 1, nb
            do i = 1, j - 1
               tmp7 = -tmp1(1, j)
               tmp8 = tmp1(1, i) + tmp7
               tmp9 = tmp8**(2)
               tmp10 = -tmp1(2, j)
               tmp11 = tmp1(2, i) + tmp10
               tmp12 = tmp11**(2)
               tmp13 = tmp9 + tmp12
               tmp14 = -tmp1(3, j)
               tmp15 = tmp1(3, i) + tmp14
               tmp16 = tmp15**(2)
               tmp17 = tmp13 + tmp16
               tmp18 = 1.0_wp/sqrt(tmp17)
               tmp6(i, j) = tmp18
               tmp6(j, i) = tmp18
            end do
         end do
         !$omp end parallel do
      end block
      do i = 1, nb
         tmp19 = 1.0_wp/tmp5(i)
         tmp20 = 12.566370614359172_wp*tmp19
         tmp21 = sqrt(tmp20)
         tmp22 = 1.0694_wp*tmp21
         tmp6(i, i) = tmp22
      end do
      block
         real(wp) :: tmp24, tmp25, tmp26, tmp27, tmp28, tmp29, tmp30, tmp31, tmp32, tmp33, tmp34, &
                     tmp35, tmp36, tmp37, tmp38, tmp39, tmp40, tmp41, tmp42, tmp43, tmp44, tmp45, &
                     tmp46, tmp47, tmp48, tmp49, tmp50, tmp51

         !$omp parallel do schedule(dynamic, 16) &
         !$omp& private(i) &
         !$omp& shared(nb, tmp1, tmp2, tmp23) &
         !$omp& default(private)
         do j = 1, nb
            do i = 1, j - 1
               tmp24 = -tmp1(1, j)
               tmp25 = tmp1(1, i) + tmp24
               tmp26 = tmp2(1, j)*tmp25
               tmp27 = -tmp1(2, j)
               tmp28 = tmp1(2, i) + tmp27
               tmp29 = tmp28*tmp2(2, j)
               tmp30 = tmp26 + tmp29
               tmp31 = -tmp1(3, j)
               tmp32 = tmp1(3, i) + tmp31
               tmp33 = tmp32*tmp2(3, j)
               tmp34 = tmp30 + tmp33
               tmp35 = tmp25**(2)
               tmp36 = tmp28**(2)
               tmp37 = tmp35 + tmp36
               tmp38 = tmp32**(2)
               tmp39 = tmp37 + tmp38
               tmp40 = 1.0_wp/sqrt(tmp39)
               tmp41 = tmp40**(3)
               tmp42 = tmp34*tmp41
               tmp23(i, j) = tmp42
               tmp43 = -tmp25
               tmp44 = tmp2(1, i)*tmp43
               tmp45 = -tmp28
               tmp46 = tmp45*tmp2(2, i)
               tmp47 = tmp44 + tmp46
               tmp48 = -tmp32
               tmp49 = tmp48*tmp2(3, i)
               tmp50 = tmp47 + tmp49
               tmp51 = tmp50*tmp41
               tmp23(j, i) = tmp51
            end do
         end do
         !$omp end parallel do
      end block
      do i = 1, nb
         tmp52 = tmp3(i) + tmp4(i)
         tmp53 = 1.0_wp/tmp5(i)
         tmp54 = 12.566370614359172_wp*tmp53
         tmp55 = sqrt(tmp54)
         tmp56 = tmp52*tmp55
         tmp57 = (-0.26735_wp)*tmp56
         tmp23(i, i) = tmp57
      end do
      do i = 1, nb
         tmp58(:, i) = tmp5(i)*tmp23(:, i)
      end do
      call gemm(tmp58, tmp6, tmp59)
      tmp60 = transpose(tmp59)
      tmp61 = tmp59 + tmp60
      tmp62 = self%c1*tmp61
      a = tmp6 + tmp62
   end subroutine ssvpe_point_op4_assemble_block

end module pcmgen_point_ssvpe
